<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">			&quot;path&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/usr/local/bin/my-runc-replacement&quot;,</span></span>
